import java.util.Collections;
import java.util.ArrayList;
import java.util.List;

public class ThreadSafeCollectionDemo {
    private final List<String> cache = Collections.synchronizedList(new ArrayList<>());

    public void updateAndSort(String newItem) {
        // Compound operation requires explicit external synchronization
        synchronized (cache) {
            cache.add(newItem);
            Collections.sort(cache);
        }
    }

    public List<String> getReadOnlyView() {
        // Exposes a safe, unmodifiable view to callers
        return Collections.unmodifiableList(cache);
    }
}
